fn trace(a: Vec<Vec<f32>>, offset: i32) -> f32 {
    let mut sum = 0.0f32;
    for (i, row) in a.iter().enumerate() {
        // Compute the shifted column index in signed form
        let j_signed = i as i32 + offset;
        // Only proceed if the index is non‐negative
        if j_signed < 0 {
            continue;
        }
        let j = j_signed as usize;
        // Check bounds for this particular row
        if j < row.len() {
            sum += row[j];
        }
    }
    sum
}

